package de.androidcrypto.android_hce_emulate_a_creditcard;

import static de.androidcrypto.android_hce_emulate_a_creditcard.EmvCardEmulatorCore.hexBytes;
import static de.androidcrypto.android_hce_emulate_a_creditcard.Utils.hexStringToByteArray;

import java.util.HashMap;
import java.util.Map;

/**
 * Research / interoperability fixture: emulates a Mastercard carrying the EMVCo
 * 3-D Secure test PAN 5555555555554444. No real cardholder data is present;
 * recorded cryptograms are replayed for reader-compatibility lab testing only.
 */
public class HceCcEmulationServiceMastercard extends BaseHceEmulationService {

    @Override
    protected String getSchemeName() {
        return "mastercard";
    }

    @Override
    protected int getInitialAtc() {
        return 0x0001;
    }

    @Override
    protected void initProfile() {
        Map<String, byte[]> records = new HashMap<String, byte[]>();
        records.put("8/1", hexStringToByteArray("70759F6C0200019F6206000000000F009F63060000000000FE563435353535353535353535343434345E202F5E323430333232313237393433323930303030303030303030303030303030309F6401029F65020F009F660200FE9F6B135555555555554444D24032212794329000000F9F670102"));
        records.put("10/1", hexStringToByteArray(""));
        records.put("20/1", hexStringToByteArray(""));
        records.put("20/2", hexStringToByteArray(""));
        Map<String, byte[]> dataObjects = new HashMap<String, byte[]>();
        dataObjects.put("9F13", hexBytes("00000000000000000000000000000000"));
        dataObjects.put("9F17", hexBytes("00000000"));
        setProfile(
                hexStringToByteArray("6F3C840E325041592E5359532E4444463031A52ABF0C2761254F07A000000004101050104465626974204D6173746572436172648701019F0A0400010101"),
                hexStringToByteArray("6F528407A0000000041010A54750104465626974204D6173746572436172649F12104465626974204D6173746572436172648701019F1101015F2D046465656EBF0C119F0A04000101019F6E0702800000303000"),
                hexStringToByteArray("771282021980940C080101001001010120010200"),
                records,
                hexStringToByteArray("7712820297809408080101001001010120010200"),
                dataObjects);
    }
}
